selector-segmentado-2.js:
document.querySelectorAll(".tabs").forEach(t => t.onclick = e => {
  const b = e.target.closest("button"); if (!b) return;
  t.querySelectorAll("button").forEach(x => x.classList.toggle("on", x === b));
});
